	/**
	 * Method to retrieve the FinancialInstitution via FinancialInstitutionFetchOneSummary
	 * @param 	summary FinancialInstitutionFetchOneSummary
	 * @return 	FinancialInstitutionFetchOneResponse
	 */
	public FinancialInstitution getFinancialInstitution( FinancialInstitutionFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "FinancialInstitutionFetchOneSummary arg cannot be null" );

		FinancialInstitution entity = null;
		UUID id = summary.getFinancialInstitutionId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a FinancialInstitution using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


